function bind(){document.querySelectorAll('[data-act]').forEach(b=>b.addEventListener('click',()=>action(b.dataset.act)));if(state.page==='imports'){const drop=$('drop');drop.addEventListener('dragover',e=>{e.preventDefault();drop.classList.add('over')});drop.addEventListener('dragleave',()=>drop.classList.remove('over'));drop.addEventListener('drop',e=>{e.preventDefault();drop.classList.remove('over');filesSelected([...e.dataTransfer.files])})}}
function action(s){let [cmd,arg]=s.split(':');if(cmd==='page')return page(arg);if(cmd==='pick')return $('reports-picker').click();if(cmd==='inspect')return inspectReport(Number(arg));if(cmd==='remove'){state.reports.splice(Number(arg),1);save();return render()}if(cmd==='backup'){const blob=new Blob([JSON.stringify({type:'midir-companion-backup',data:state},null,2)],{type:'application/json'});download(blob,'midir-companion-backup.json');return}if(cmd==='restore')return $('backup-picker').click();if(cmd==='dd-stage'){state.settings.ddStage=+arg;save();return render()}if(cmd==='dd-start')return startDD();if(cmd==='dd-stop'){stopTimers();return message('Drill stopped. Self-assess whenever you are ready.')}if(cmd==='dd-advance')return assessDD('advance');if(cmd==='dd-repeat')return assessDD('repeat');if(cmd==='dd-easier')return assessDD('easier');if(cmd==='pos'){runtime.position=+arg;return render()}if(cmd==='shape'){runtime.attack=arg;return render()}if(cmd==='position-commit'){const el=$('position-feedback');if(el)el.textContent=arg==='attack'?'You committed to immediate execution. Reflect: how much damage opportunity would movement have cost?':'You committed to improving position. Reflect: do the extra potential targets justify the travel?';return}if(cmd==='as-start')return startAS();if(cmd==='as-stop')return stopAS();if(cmd==='as-config'){for(const input of document.querySelectorAll('[data-sk]')){const id=input.dataset.sk,key=input.dataset.field;state.asSkillSettings[id]??={};state.asSkillSettings[id][key]=key==='key'?input.value:Number(input.value)||0}save();return render()}if(cmd==='as-pattern'){const pattern=D.arcana.as.patterns[Number(arg)];state.asSequence=pattern.steps.map(id=>{const skill=D.arcana.as.skills.find(s=>s.id===id);return state.asSkillSettings[id]?.key||skill.key}).join(' ');save();return render()}if(cmd==='acad-mode'){academyUI.mode=arg;academyUI.answer=null;academyUI.missingSelected=[];academyUI.shown=false;if(arg==='flash')startFlashDeck();if(arg==='missing'&&!missingPractice.current)generateMissingScenario();return render()}if(cmd==='acad-prev'){academyUI.lesson=Math.max(0,academyUI.lesson-1);return render()}if(cmd==='acad-next'){academyUI.lesson=Math.min(debuffTracks.length-1,academyUI.lesson+1);return render()}if(cmd==='acad-reviewed'){state.academyHistory.push({kind:'review',lesson:academyUI.lesson,date:Date.now()});save();return message('Practice noted.')}if(cmd==='acad-card'){academyUI.card=+arg;return render()}if(cmd==='acad-flash-card'){academyUI.card=+arg;academyUI.flip=false;academyUI.mode='flash';startFlashDeck(debuffCards[academyUI.card]?.id);return render()}if(cmd==='acad-flip'){academyUI.flip=!academyUI.flip;return render()}if(cmd==='acad-flash-next'){nextFlashCard();return render()}if(cmd==='acad-shuffle'){resetFlashRound(currentFlashId());return render()}if(cmd==='acad-set-aside'){setAsideFlashCard();return render()}if(cmd==='acad-restore'){restoreFlashCard(arg);return render()}if(cmd==='acad-restore-all'){state.academySetAside=[];save();resetFlashRound(currentFlashId());return render()}if(cmd==='acad-source'){const v=new Set(academyUI.missingSelected||[]);v.has(arg)?v.delete(arg):v.add(arg);academyUI.missingSelected=[...v];academyUI.shown=false;return render()}if(cmd==='acad-source-clear'){academyUI.missingSelected=[];academyUI.shown=false;return render()}if(cmd==='acad-explain'){academyUI.shown=true;return render()}if(cmd==='acad-missing-next'){academyUI.question++;generateMissingScenario();academyUI.missingSelected=[];academyUI.shown=false;return render()}if(cmd==='acad-reflect'){state.academyHistory.push({kind:'missing-debuff',question:academyUI.question,selectedSources:[...academyUI.missingSelected],missingGroups:[...missingScenario().missing],date:Date.now()});save();return message('Practice reflection saved without a grade.')}if(cmd==='debuff-prev'){runtime.academy=Math.max(0,runtime.academy-1);return render()}if(cmd==='debuff-next'){runtime.academy=Math.min(D.debuffLessons.length-1,runtime.academy+1);return render()}if(cmd==='debuff-mark'){state.academyHistory.push({kind:'review',lesson:runtime.academy,date:Date.now()});save();return render()}if(cmd==='debuff-choice'){runtime.academyChoice=+arg;runtime.academyReveal=false;return render()}if(cmd==='debuff-reveal'){runtime.academyReveal=true;return render()}if(cmd==='debuff-scenario-next'){runtime.scenario=(runtime.scenario+1)%D.debuffScenarios.length;runtime.academyChoice=null;runtime.academyReveal=false;return render()}if(cmd==='debuff-save'){state.academyHistory.push({kind:'scenario',scenario:runtime.scenario,choice:runtime.academyChoice,date:Date.now()});save();return message('Reflection saved without a grade.')}if(cmd==='encounter')return $('encounter-extra').innerHTML=pane('Encounter focus',`<h3>${esc(D.encounters[+arg].name)}</h3><p>${esc(D.encounters[+arg].description)}</p><p>Discuss the decision you would make when the phase begins. For repeated-critical phases, rehearse the same decision several times.</p>`);if(cmd==='evidence')return evidence(arg);if(cmd==='milestone-save'){const input=$('milestone');if(input.value.trim()){state.marks.push({text:input.value.trim().slice(0,240),date:Date.now()});save();render()}return}}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}$('reports-picker').addEventListener('change',e=>{filesSelected([...e.target.files]);e.target.value='' });$('arcana').value=state.arcana;$('arcana').addEventListener('change',e=>{stopTimers();state.arcana=e.target.value;save();render()});document.querySelectorAll('nav button').forEach(b=>b.addEventListener('click',()=>page(b.dataset.page)));document.addEventListener('keydown',asKey);document.addEventListener('change',e=>{if(e.target.id==='backup-picker'&&e.target.files[0]){e.target.files[0].text().then(t=>{try{const b=JSON.parse(t);if(b.type!=='midir-companion-backup'||!b.data||!Array.isArray(b.data.reports))throw Error('Invalid backup');if(!confirm('Replace this browser profile and imported report index with the backup?'))return;state={...state,...b.data};save();render()}catch(e){message(e.message)}})}});
/* Vault v0.3: imported HTML is the primary artifact. JSON remains an optional data-only input.
   An independent IndexedDB object store holds full HTML reports outside localStorage.
   Metrics are computed conservatively from actual exporter fields. */
const vaultDbName='midir-vault-archive-v1';
function openVaultDb(){return new Promise((resolve,reject)=>{if(!window.indexedDB)return reject(Error('IndexedDB unavailable'));const q=indexedDB.open(vaultDbName,1);q.onupgradeneeded=()=>{if(!q.result.objectStoreNames.contains('reports'))q.result.createObjectStore('reports')};q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error)})}
async function storeHtml(id,html){const db=await openVaultDb();return new Promise((resolve,reject)=>{const tx=db.transaction('reports','readwrite');tx.objectStore('reports').put(html,id);tx.oncomplete=()=>{db.close();resolve()};tx.onerror=()=>{db.close();reject(tx.error)}})}
async function readHtml(id){const db=await openVaultDb();return new Promise((resolve,reject)=>{const tx=db.transaction('reports');const req=tx.objectStore('reports').get(id);req.onsuccess=()=>{db.close();resolve(req.result)};req.onerror=()=>{db.close();reject(req.error)}})}
async function removeHtml(id){try{const db=await openVaultDb();await new Promise((resolve,reject)=>{const tx=db.transaction('reports','readwrite');tx.objectStore('reports').delete(id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});db.close()}catch(e){console.warn(e)}}
const vaultPlayers=r=>r.players.filter(p=>p.skills?.some(x=>Number(x.totalDamage??x.total)>0));
function participantStats(r,p){const report=r.reportPlayers?.find(x=>x.name===p.name);const skills=p.skills||[];const damage=skills.reduce((n,x)=>n+(Number(x.totalDamage??x.total??0)||0),0);const hasReportDamage=report?.damage!=null&&Number.isFinite(Number(report.damage)),hasReportDps=report?.dps!=null&&Number.isFinite(Number(report.dps));return {damage:hasReportDamage?Number(report.damage):damage,dps:hasReportDps?Number(report.dps):r.duration>0?damage/r.duration:null,deathCount:Array.isArray(p.deathTimes)?p.deathTimes.length:report?.deaths!=null&&Number.isFinite(Number(report.deaths))?Number(report.deaths):null,damageTaken:p.damageTaken??null,topHit:Math.max(0,...skills.map(x=>Number(x.biggest??x.maxHit??0)||0)),duration:r.duration}}
function verifiedBossClear(r){if(r.provenance!=='companion-v1')return false;return [1,3].some(g=>gateForTarget(r,g).some(a=>a.complete===true))}
function skillRecordMap(p){const out=new Map();for(const sk of p.skills||[]){const name=String(sk.skillId??sk.id??sk.name??'').trim();if(!name)continue;const amount=Number(sk.biggest??sk.maxHit??0);if(Number.isFinite(amount)&&amount>0)out.set(name,Math.max(out.get(name)||0,amount))}return out}
function vaultDate(r){const n=Number(r.sessionStart);return n>1000000000?new Date(n*1000).toLocaleString():r.importedAt?new Date(r.importedAt).toLocaleString():'Unknown session date'}
function vaultArcana(p){return p.arcana?String(p.arcana):'Arcana unknown'}
function vaultMetricEvents(r,previous){const events=[];const peers=chosenPlayer(r)?[chosenPlayer(r)]:[];for(const p of peers){const now=participantStats(r,p),prior=previous?.players.find(x=>x.name===p.name);const was=prior?participantStats(previous,prior):null;const common={reportId:r.id,encounter:r.encounter,player:p.name,date:r.importedAt||Date.now()};
  // A full deathless completion may be celebrated on a first import, but only with explicit clear evidence.
  if(verifiedBossClear(r)&&now.deathCount===0&&!state.metricMilestones.some(e=>e.type==='first-deathless'&&e.encounter===r.encounter&&e.player===p.name))events.push({...common,type:'first-deathless',title:'Untouchable!',detail:`Your first verified deathless clear recorded in the Vault for ${r.encounter}!`,magnitude:30,delta:0,evidence:'clear + death timestamps'});
  if(!was)continue;
  if(now.dps!==null&&was.dps!==null&&now.dps>was.dps&&now.dps-was.dps>=10000&&was.dps>0){const pct=(now.dps/was.dps-1)*100;events.push({...common,type:'dps',title:'Damage breakthrough!',detail:`Congrats! Your damage improved by ${pct.toFixed(1)}% since your last import!`,magnitude:pct,delta:Math.round(now.dps-was.dps),evidence:'reported DPS'})}
  if(now.damageTaken!==null&&was.damageTaken!==null&&was.damageTaken>0&&now.damageTaken<was.damageTaken){const pct=(1-now.damageTaken/was.damageTaken)*100;events.push({...common,type:'taken',title:'Stronger defense!',detail:`You took ${pct.toFixed(1)}% less damage than your last ${r.encounter} import.`,magnitude:pct,delta:was.damageTaken-now.damageTaken,evidence:'recorded damage taken'})}
  if(now.deathCount!==null&&was.deathCount!==null&&now.deathCount===0&&was.deathCount>0){events.push({...common,type:'deathless',title:'Deathless improvement!',detail:`You went from ${was.deathCount} recorded deaths to zero against ${r.encounter}.`,magnitude:100,delta:was.deathCount,evidence:'death event counts'})}
  if(now.deathCount!==null&&was.deathCount!==null&&now.deathCount<was.deathCount&&now.deathCount>0){events.push({...common,type:'fewer-deaths',title:'Fewer falls!',detail:`You reduced recorded deaths from ${was.deathCount} to ${now.deathCount} against ${r.encounter}.`,magnitude:100*(was.deathCount-now.deathCount)/Math.max(1,was.deathCount),delta:was.deathCount-now.deathCount,evidence:'death event counts'})}
  if(now.topHit>0&&was.topHit>0&&now.topHit>was.topHit){const pct=(now.topHit/was.topHit-1)*100;events.push({...common,type:'hit',title:'New biggest hit!',detail:`Your largest recorded hit increased by ${pct.toFixed(1)}% in ${r.encounter}.`,magnitude:pct,delta:now.topHit-was.topHit,evidence:'skill hit summaries'})}
  // A total-damage milestone is descriptive, not an efficiency rating; fight duration may differ.
  if(now.damage>0&&was.damage>0&&now.damage>was.damage){const pct=(now.damage/was.damage-1)*100;if(pct>=10)events.push({...common,type:'total-damage',title:'More damage dealt!',detail:`Your recorded damage total grew by ${pct.toFixed(1)}% against ${r.encounter}. This is a raw total, not a speed or rotation grade.`,magnitude:pct,delta:now.damage-was.damage,evidence:'reported skill damage totals'})}
  const oldSkills=skillRecordMap(prior),newSkills=skillRecordMap(p);let wins=[];for(const [id,value] of newSkills){const earlier=oldSkills.get(id);if(earlier&&value>earlier)wins.push({id,pct:100*(value/earlier-1),value,earlier})}if(wins.length){wins.sort((a,b)=>b.pct-a.pct);const x=wins[0];events.push({...common,type:'skill-hit',title:'Skill-specific peak!',detail:`Skill ${x.id} hit ${x.pct.toFixed(1)}% harder than its previous recorded peak against ${r.encounter}.`,magnitude:x.pct,delta:x.value-x.earlier,evidence:'per-skill largest hits',additionalSkillRecords:wins.length})}
  if(verifiedBossClear(r)&&verifiedBossClear(previous)&&now.duration>0&&was.duration>0&&now.duration<was.duration){const pct=100*(1-now.duration/was.duration);events.push({...common,type:'faster-combat',title:'Faster boss combat!',detail:`Recorded encounter duration improved by ${pct.toFixed(1)}% (${was.duration.toFixed(1)}s → ${now.duration.toFixed(1)}s). This is not a full dungeon-clear record.`,magnitude:pct,delta:was.duration-now.duration,evidence:'verified clear + session duration'})}
}return events}
function vaultEventsForImport(r){if(r.targetScope==='selected-target')return [];const earlier=state.reports.filter(x=>chosenPlayer(x)&&x.id!==r.id&&x.encounter===r.encounter&&(x.importedAt||0)<(r.importedAt||0)).sort((a,b)=>(b.importedAt||0)-(a.importedAt||0));return vaultMetricEvents(r,earlier[0]||null)}
function celebration(events){if(!events.length)return;const best=[...events].sort((a,b)=>b.magnitude-a.magnitude)[0];const modal=document.createElement('div');modal.className='vault-modal';modal.innerHTML=`<div class="vault-modal-inner" role="dialog" aria-modal="true" aria-label="New achievement"><span class="vault-sparkle">✦ ★ ✦</span><h2>${esc(best.title)}</h2><p>${esc(best.detail)}</p><p class="hint">${events.length>1?`${events.length-1} other milestone(s) quietly saved in your Vault.`:'Saved to milestones.'}</p><button id="vault-dismiss" class="primary">Wonderful!</button></div>`;document.body.appendChild(modal);modal.querySelector('button').addEventListener('click',()=>modal.remove());}
let vaultViewerId=null;
async function viewReportInline(id){
  const r=state.reports.find(x=>x.id===id);
  if(!r)return;
  vaultViewerId=id;
  render();
  const host=$('vault-inline-content');
  if(!host)return;
  host.textContent='Loading archived report…';
  try{
    const html=await readHtml(id);
    if(vaultViewerId!==id||!$('vault-inline-content'))return;
    if(!html){host.innerHTML='<p class="hint">The original HTML is not archived for this entry. Re-import the original HTML file to attach it without duplicating your report.</p>';return}
    // The original self-contained Midir export carries its own plots, controls and data.
    // Sandbox report scripts so imported HTML cannot access Companion profile/storage.
    const frame=document.createElement('iframe');
    frame.className='vault-report-frame';
    frame.title='Midir report — '+r.name;
    frame.setAttribute('sandbox','allow-scripts allow-downloads');
    frame.setAttribute('referrerpolicy','no-referrer');
    frame.srcdoc=html;
    host.replaceChildren(frame);
    host.scrollIntoView({behavior:'smooth',block:'start'});
  }catch(e){host.textContent='Unable to load archived HTML: '+e.message}
}
function closeReportInline(){vaultViewerId=null;render()}
function openReport(id){
  // Open on the synchronous click stack before any async IndexedDB operation;
  // otherwise Chrome/Edge can block the new tab as a popup.
  const win=window.open('about:blank','_blank');
  if(!win){message('Your browser blocked the report tab. Allow popups for this file, then try again.');return;}
  win.document.title='Loading Midir report…';
  win.document.body.textContent='Opening saved Midir report…';
  readHtml(id).then(html=>{
    if(!html){win.document.body.textContent='Original HTML not stored. Please re-import this report.';return;}
    const url=URL.createObjectURL(new Blob([html],{type:'text/html;charset=utf-8'}));
    win.location.replace(url);
    setTimeout(()=>URL.revokeObjectURL(url),5*60*1000);
  }).catch(e=>{try{win.document.body.textContent='Unable to open: '+e.message}catch{} });
}
async function filesSelectedVault(files){let ok=0,fail=[],newEvents=[];for(const f of files){if(f.size>90*1024*1024){fail.push(f.name+': too large');continue}try{const content=await f.text();const r=parseReport(content,f.name);const fingerprint=JSON.stringify([r.sessionStart,r.title,r.duration,r.players.map(p=>[p.entityId,p.name,p.skills.length]),r.targets.map(t=>t.entityId)]);r.id='r'+hash(fingerprint);const existing=state.reports.find(x=>x.id===r.id);if(existing){if(/\.html?$/i.test(f.name)){try{await storeHtml(existing.id,content);existing.isHtml=true;existing.htmlSaved=true;ok++;continue}catch(e){fail.push(f.name+': unable to attach original HTML ('+e.message+')');continue}}fail.push(f.name+': already imported');continue}r.importedAt=Date.now()+ok;r.isHtml=/\.html?$/i.test(f.name);if(r.isHtml){try{await storeHtml(r.id,content);r.htmlSaved=true}catch(e){r.htmlSaved=false;fail.push(f.name+': HTML archiving unavailable ('+e.message+')')}}state.reports.push(r);const events=vaultEventsForImport(r);for(const event of events){const key=[event.reportId,event.player,event.type].join('|');if(!state.metricMilestones.some(x=>x.id===key))state.metricMilestones.push({...event,id:key})}newEvents.push(...events);ok++}catch(e){fail.push(f.name+': '+e.message)}}rebuildOwnedMilestones();save();render();message(`${ok} report(s) imported. ${fail.join(' · ')}`);celebration(newEvents)}
